<?php
namespace App\Services\Automation\Handlers;
use App\Models\AutomationRun; use App\Models\OzonAccount; use App\Services\Automation\AutomationHandlerInterface; use App\Services\Automation\AutomationProgressReporterInterface; use App\Services\Ozon\OzonConnectionService; use Throwable;
class OzonConnectionCheckHandler implements AutomationHandlerInterface { public function __construct(private readonly OzonConnectionService $service) {} public function handle(AutomationRun $run, AutomationProgressReporterInterface $progress, bool $dryRun=false): array { $progress->start(1,'Проверка подключения Ozon.'); $account=OzonAccount::query()->findOrFail((int)($run->context['ozon_account_id'] ?? 0)); try { $this->service->check($account,$run); $progress->setProgress(1,1,'Подключение подтверждено.'); return ['successful'=>true,'processed_items'=>1,'message'=>'Подключение Ozon подтверждено.']; } catch(Throwable $e) { $account->update(['last_connection_check_at'=>now(),'last_connection_error'=>$e->getMessage()]); throw $e; } } }
